pm.test("Resposta corresponde ao schema documentado de carrinhos", function () {
    const carts = pm.response.json();
    pm.expect(carts).to.be.an("array");
    carts.forEach(function (cart) {
        pm.expect(cart).to.be.an("object");
        ["id", "userId"].forEach(function (field) {
            pm.expect(cart, "Carrinho." + field + " obrigatorio").to.have.property(field);
            pm.expect(cart[field], "Carrinho." + field + " deve ser inteiro").to.be.a("number");
            pm.expect(Number.isInteger(cart[field]), "Carrinho." + field + " deve ser inteiro").to.eql(true);
        });
        pm.expect(cart, "Carrinho.products obrigatorio").to.have.property("products");
        pm.expect(cart.products, "Carrinho.products deve ser array").to.be.an("array");
        cart.products.forEach(function (product) {
            pm.expect(product).to.be.an("object");
            pm.expect(product, "Produto.id obrigatorio").to.have.property("id");
            pm.expect(product.id, "Produto.id deve ser inteiro").to.be.a("number");
            pm.expect(Number.isInteger(product.id), "Produto.id deve ser inteiro").to.eql(true);
            ["title", "description", "category", "image"].forEach(function (field) {
                pm.expect(product, "Produto." + field + " obrigatorio").to.have.property(field);
                pm.expect(product[field], "Produto." + field + " deve ser string").to.be.a("string");
            });
            pm.expect(product, "Produto.price obrigatorio").to.have.property("price");
            pm.expect(product.price, "Produto.price deve ser numero").to.be.a("number");
        });
    });
    const summary = carts.map(function (cart) {
        return {
            id: cart.id,
            userId: cart.userId,
            date: cart.date || "(n?o informado)",
            productsCount: cart.products.length,
            productFields: cart.products.length ? Object.keys(cart.products[0]).join(", ") : "(sem itens)"
        };
    });
    pm.visualizer.set("<h3>Carrinhos retornados: {{count}}</h3><p>Campos exibidos conforme os dados retornados.</p><table><thead><tr><th>ID</th><th>Usu?rio</th><th>Data (campo adicional)</th><th>Qtd. produtos</th><th>Campos do produto</th></tr></thead><tbody>{{#each carts}}<tr><td>{{id}}</td><td>{{userId}}</td><td>{{date}}</td><td>{{productsCount}}</td><td>{{productFields}}</td></tr>{{/each}}</tbody></table>", { count: summary.length, carts: summary });
});

